package com.gamehub.application.service;

import com.gamehub.infrastructure.*;
import java.sql.SQLException;
import java.time.Instant;
import java.util.*;

/** Focused application workflows for tournament registration. */
public final class TournamentRegistrationService extends ApplicationSupport {
    private final PaymentRepository paymentRepository;
    private final TeamRepository teamRepository;
    private final TournamentRepository tournamentRepository;
    private final TournamentRegistrationRepository registrationRepository;
    public TournamentRegistrationService(Database db) { super(db); paymentRepository=new PaymentRepository(db.connection()); teamRepository=new TeamRepository(db.connection()); tournamentRepository=new TournamentRepository(db.connection()); registrationRepository=new TournamentRegistrationRepository(db.connection()); }
    public List<String> registrations(long tournamentId)throws SQLException {List<String> out=new ArrayList<>();try(var p=registrationRepository.registrations(tournamentId);var r=p.executeQuery()){while(r.next())out.add("#"+r.getLong(1)+" | "+r.getString(2)+" | "+r.getString(3));}return out;}
    public long registerTournament(long tournamentId,long userId)throws SQLException {requireCustomer(userId);transactions.begin();try{long fee;int capacity;try(var s=tournamentRepository.registerTournament(tournamentId);var r=s.executeQuery()){if(!r.next())throw new IllegalArgumentException("Tournament not found");validateRegistration(r.getString(2),r.getString(4),"INDIVIDUAL",r.getString(5),r.getString(6));fee=r.getLong(1);capacity=r.getInt(3);}checkCapacity(tournamentId,capacity);try(var s=registrationRepository.registerTournamentQuery2(tournamentId,userId);var r=s.executeQuery()){if(r.next()&&r.getInt(1)>0)throw new IllegalStateException("Already registered");}long id;try(var s=registrationRepository.registerTournamentQuery3(tournamentId,userId,fee,fee==0?"PAID":"PENDING",fee==0?"CONFIRMED":"PENDING",now())){s.executeUpdate();try(var k=s.getGeneratedKeys()){if(!k.next())throw new SQLException("Registration was not created");id=k.getLong(1);}}if(fee>0)try(var s=paymentRepository.registerTournament(userId,id,fee,now())){s.executeUpdate();}audit(userId,"REGISTRATION",id,"CREATED",fee==0?"CONFIRMED":"PENDING_PAYMENT");transactions.commit();return id;}catch(SQLException|RuntimeException e){transactions.rollback();throw e;}finally{transactions.restoreAutoCommit();}}
    private void checkCapacity(long tournamentId,int capacity)throws SQLException{try(var s=registrationRepository.registerTournament(tournamentId);var r=s.executeQuery()){if(r.next()&&r.getInt(1)>=capacity)throw new IllegalStateException("Tournament is full");}}
    private static void validateRegistration(String status,String entrant,String expected,String opens,String closes){Instant now=Instant.now();if(!Set.of("OPEN","REGISTRATION_OPEN").contains(status)||!expected.equals(entrant))throw new IllegalStateException("This tournament is not open for "+expected.toLowerCase(Locale.ROOT)+" registration");if(opens!=null&&!opens.isBlank()&&now.isBefore(Instant.parse(opens))||closes!=null&&!closes.isBlank()&&!now.isBefore(Instant.parse(closes)))throw new IllegalStateException("Registration is outside the tournament's registration window");}
    public List<String> myRegistrations(long userId)throws SQLException{requireCustomer(userId);List<String> out=new ArrayList<>();try(var s=registrationRepository.myRegistrations(userId);var r=s.executeQuery()){while(r.next())out.add("#"+r.getLong(1)+" | "+r.getString(2)+" | "+r.getString(3)+" | "+r.getString(4)+" | PKR "+java.math.BigDecimal.valueOf(r.getLong(5),2));}return out;}
    public long registerTournamentTeam(long tournamentId,long captainId,long teamId)throws SQLException{requireCustomer(captainId);transactions.begin();try{long fee;String status,entrant;int capacity;try(var q=tournamentRepository.registerTournamentTeam(tournamentId);var r=q.executeQuery()){if(!r.next())throw new IllegalStateException("Tournament not found");fee=r.getLong(1);status=r.getString(2);entrant=r.getString(3);capacity=r.getInt(4);validateRegistration(status,entrant,"TEAM",r.getString(5),r.getString(6));}try(var q=teamRepository.registerTournamentTeam(teamId);var r=q.executeQuery()){if(!r.next()||r.getLong(1)!=captainId||r.getInt(2)<2)throw new SecurityException("Only an eligible captain may register a team");}try(var q=registrationRepository.registeredTeam(teamId);var r=q.executeQuery()){if(r.next())throw new IllegalStateException("Team roster is locked while registered in a tournament");}try(var q=registrationRepository.registerTournamentTeam(tournamentId,teamId);var r=q.executeQuery()){if(r.next()&&r.getInt(1)>0)throw new IllegalStateException("Team is already registered");}checkCapacity(tournamentId,capacity);long id;try(var p=registrationRepository.registerTournamentTeamQuery3(tournamentId,teamId,fee,fee==0?"PAID":"PENDING",fee==0?"CONFIRMED":"PENDING",now())){p.executeUpdate();try(var k=p.getGeneratedKeys()){if(!k.next())throw new SQLException("Registration was not created");id=k.getLong(1);}}if(fee>0)try(var p=paymentRepository.registerTournamentTeam(captainId,id,fee,now())){p.executeUpdate();}audit(captainId,"REGISTRATION",id,"CREATED",fee==0?"CONFIRMED":"PENDING_PAYMENT");transactions.commit();return id;}catch(SQLException|RuntimeException e){transactions.rollback();throw e;}finally{transactions.restoreAutoCommit();}}
    public List<String> tournaments()throws Exception{return new TournamentService(db).tournaments();}
    public List<String> open()throws SQLException{return new TournamentService(db).openForRegistration();}
    public List<String> teams(long customer)throws Exception{return new TeamService(db).captainTeams(customer);}
    public long solo(long tournament,long customer)throws Exception{return registerTournament(tournament,customer);}
    public long team(long tournament,long captain,long team)throws Exception{return registerTournamentTeam(tournament,captain,team);}
}
